#include <vector>
#include <algorithm>

class Solution {
public:
    int longestSemiRepeatingSubarray(std::vector<int>& nums) {
        int n = nums.size();
        if (n <= 2) return n;

        int left = 0;
        int repeat_count = 0;
        int max_len = 1;

        for (int right = 1; right < n; ++right) {
            if (nums[right] == nums[right - 1]) {
                repeat_count++;
            }
            while (repeat_count > 1) {
                if (nums[left + 1] == nums[left]) {
                    repeat_count--;
                }
                left++;
            }
            max_len = std::max(max_len, right - left + 1);
        }
        return max_len;
    }
};

class Solution {
    public int longestSemiRepeatingSubarray(int[] nums) {
        int n = nums.length;
        if (n <= 2) return n;

        int left = 0;
        int repeatCount = 0;
        int maxLen = 1;

        for (int right = 1; right < n; right++) {
            if (nums[right] == nums[right - 1]) {
                repeatCount++;
            }
            while (repeatCount > 1) {
                if (nums[left + 1] == nums[left]) {
                    repeatCount--;
                }
                left++;
            }
            maxLen = Math.max(maxLen, right - left + 1);
        }
        return maxLen;
    }
}

var longestSemiRepeatingSubarray = function(nums) {
